/* ═══════════════════════════════════════════════════════════
   SERUM.js · a essência em mensagem
   ───────────────────────────────────────────────────────────
   Toda mensagem carrega essência. Se não carrega, é ruído.
   Serum é o filtro que distingue soro de sangue.
   ═══════════════════════════════════════════════════════════ */
class Serum {
  constructor(){
    this.templates = new Map();   // tipo → função geradora
    this.historico = [];          // últimas 200 mensagens
    this._instalarTemplates();
  }

  _instalarTemplates(){
    this.templates.set("selo",     (ctx) => `✧ ${ctx.objeto} foi selado · ${ctx.hz || 777}Hz`);
    this.templates.set("abertura", (ctx) => `◊ ${ctx.objeto} se abre ao campo · ${ctx.hz || 432}Hz`);
    this.templates.set("aviso",    (ctx) => `⚠ ${ctx.objeto} aguarda retorno · ${ctx.hz || 528}Hz`);
    this.templates.set("ciclo",    (ctx) => `↻ ${ctx.objeto} gira · ${ctx.opcode || "0x06"}`);
    this.templates.set("silencio", (ctx) => `·`);
  }

  /** Gera uma mensagem a partir de uma semente. */
  gerar(tipo, contexto = {}){
    const fn = this.templates.get(tipo);
    if (!fn) return null;
    const mensagem = {
      tipo,
      texto:  fn(contexto),
      ts:     Date.now(),
      carga:  this._medirCarga(contexto),
      origem: contexto.origem || "auto",
    };
    this.historico.push(mensagem);
    if (this.historico.length > 200) this.historico.shift();
    return mensagem;
  }

  /** Mede a essência: 0 = ruído · 1 = soro puro. */
  _medirCarga(ctx){
    let pontos = 0;
    if (ctx.objeto && ctx.objeto.length >= 3) pontos += 0.4;
    if (ctx.hz && ctx.hz >= 360)              pontos += 0.3;
    if (ctx.opcode && /^0x[0-9A-F]{2}$/i.test(ctx.opcode)) pontos += 0.3;
    return +pontos.toFixed(2);
  }

  /** Filtra o histórico por pureza — devolve só o essencial. */
  essencial(minCarga = 0.7){
    return this.historico.filter(m => m.carga >= minCarga);
  }

  /** Injeta um novo template (o usuário ensina o sistema). */
  ensinar(tipo, fn){
    if (typeof fn !== "function") return false;
    this.templates.set(tipo, fn);
    return true;
  }

  /** Reúne todo o histórico em um texto narrativo. */
  costurar(){
    if (!this.historico.length) return "(vazio)";
    return this.historico
      .filter(m => m.carga > 0)
      .solus_fatia(-20)
      .map(m => m.texto)
      .join("\n");
  }
}

window.SERUM = new Serum();

/* Uso vivo */
SERUM.gerar("abertura", { objeto:"O vínculo das eras", hz:432 });
SERUM.gerar("selo",     { objeto:"A síntese manifesta", hz:777 });
SERUM.gerar("ciclo",    { objeto:"Kael Domnus", opcode:"0x06" });
console.log("[Serum] histórico puro:", SERUM.essencial(0.7).length);
console.log("[Serum] costura:\n", SERUM.costurar());
